<template>
  <view class="my-questions-container" :class="{ 'dark-mode': darkMode }">
    <view class="header" :class="{ 'dark-header': darkMode }">
      <text class="title">我的提问</text>
      <text class="subtitle">共 {{ questions.length }} 个问题</text>
    </view>
    
    <!-- 问题列表 -->
    <view class="questions-list" v-if="questions.length > 0">
      <view 
        class="question-card" 
        :class="{ 'dark-card': darkMode }"
        v-for="question in questions" 
        :key="question.id"
        @click="goToQaDetail(question)"
      >
        <view class="question-header">
          <view class="question-category" :class="['category-' + (question.category || 'other'), { 'dark-category': darkMode }]">
            {{ question.categoryName || question.category || '其他' }}
          </view>
          <text class="question-status" :class="{ 'status-answered': question.answers > 0, 'dark-status': darkMode, 'dark-status-answered': darkMode && question.answers > 0 }">
            {{ question.answers > 0 ? '已有回答' : '等待回答' }}
          </text>
        </view>
        
        <text class="question-title" :class="{ 'dark-text': darkMode }">{{ question.title }}</text>
        <text class="question-content" :class="{ 'dark-content': darkMode }">{{ question.content }}</text>
        
        <!-- 问题图片 -->
        <view class="question-images" v-if="question.images && question.images.length > 0">
          <image 
            class="question-image" 
            v-for="(img, idx) in question.images.slice(0, 3)" 
            :key="idx"
            :src="img" 
            mode="aspectFill"
          ></image>
          <text class="more-images" :class="{ 'dark-more-images': darkMode }" v-if="question.images.length > 3">+{{ question.images.length - 3 }}</text>
        </view>
        
        <view class="question-footer" :class="{ 'dark-footer': darkMode }">
          <view class="question-stats">
            <text class="stat-item" :class="{ 'dark-stat': darkMode }">👁️ {{ question.views || 0 }}</text>
            <text class="stat-item" :class="{ 'dark-stat': darkMode }">💬 {{ question.answers || 0 }}</text>
            <text class="stat-item" :class="{ 'dark-stat': darkMode }">👍 {{ question.likes || 0 }}</text>
          </view>
          <text class="question-time" :class="{ 'dark-time': darkMode }">{{ question.time }}</text>
        </view>
        
        <!-- 新问题标记 -->
        <view class="new-badge" v-if="question.isNew">新</view>
      </view>
    </view>
    
    <!-- 空状态 -->
    <view class="empty-state" v-else>
      <text class="empty-icon" :class="{ 'dark-empty-icon': darkMode }">📋</text>
      <text class="empty-text" :class="{ 'dark-text': darkMode }">暂无提问</text>
      <text class="empty-desc" :class="{ 'dark-desc': darkMode }">去提出你的第一个问题吧</text>
      <button class="go-ask-btn" :class="{ 'dark-btn': darkMode }" @click="goToAsk">去提问</button>
    </view>
    
    <!-- 开发者信息 -->
    <view class="dev-info" :class="{ 'dark-dev': darkMode }">
      <text>开发者：李阳杰</text>
      <text>学号：2227010134</text>
    </view>
  </view>
</template>

<script>
export default {
  data() {
    return {
      darkMode: false,
      questions: [],
      userInfo: {}
    }
  },
  onLoad() {
    // 获取深色模式状态
    const app = getApp()
    this.darkMode = app?.globalData?.darkMode || false
    
    // 监听深色模式变化
    uni.$on('darkModeChange', (darkMode) => {
      this.darkMode = darkMode
    })
  },
  onShow() {
    // 刷新深色模式状态
    const app = getApp()
    this.darkMode = app?.globalData?.darkMode || false
    
    this.checkLoginStatus()
    this.loadMyQuestions()
  },
  onUnload() {
    // 移除监听
    uni.$off('darkModeChange')
  },
  methods: {
    checkLoginStatus() {
      const userInfo = uni.getStorageSync('userInfo')
      if (!userInfo) {
        uni.showToast({
          title: '请先登录',
          icon: 'none'
        })
        setTimeout(() => {
          uni.navigateBack()
        }, 1500)
        return
      }
      this.userInfo = userInfo
    },
    
    loadMyQuestions() {
      // 从本地存储加载所有问题
      const allQuestions = uni.getStorageSync('allQuestions') || []
      
      // 过滤出当前用户的问题
      this.questions = allQuestions.filter(q => 
        q.author.id === this.userInfo.userId || 
        (q.author.id === 'anonymous' && q.isAnonymous && this.userInfo.userId)
      ).sort((a, b) => b.id - a.id) // 按时间倒序
    },
    
    goToQaDetail(question) {
      uni.navigateTo({
        url: '/pages/qa-detail/qa-detail?id=' + question.id
      })
    },
    
    goToAsk() {
      uni.navigateTo({
        url: '/pages/ask/ask'
      })
    }
  }
}
</script>

